/bin/bash -lc "python - <<'PY'
import numpy as np,cv2
S=np.load('source_pixels.npz')['rgb']; p=np.load('pixels.npz')['pixels']; O=np.stack([p>>16,(p>>8)&255,p&255],-1).transpose(2,0,1,3).astype('uint8')
B=np.median(S[60:90],axis=0).astype('uint8')
def comps(im):
 d=np.max(abs(im.astype(int)-B.astype(int)),2); Y,X=np.indices(d.shape)
 m=((d>25)&(Y>50)&(Y<100)&(X>80)).astype('uint8')
 n,l,st,cen=cv2.connectedComponentsWithStats(m,8)
 q=[]
 for i in range(1,n):
  x,y,w,h,a=st[i]
  if a>20 and x>110:q.append((int(a),round(cen[i,0],1),round(cen[i,1],1),(x,y,w,h)))
 return sorted(q,reverse=True)
for t in range(15): print(t, 'src-time',t*.75,comps(O[t])[:2])
PY"
